export interface ManuscriptDraft {
  title: string;
  coverToken?: string;
  coverBytes?: readonly number[];
}

export interface ManuscriptRecord {
  title: string;
  coverToken?: string;
}

export interface BinaryDepot {
  put(bytes: readonly number[]): Promise<string>;
}

export interface ManuscriptStore {
  save(record: ManuscriptRecord): Promise<ManuscriptRecord>;
}

export class ManuscriptPublisher {
  constructor(
    private readonly depot: BinaryDepot,
    private readonly store: ManuscriptStore,
  ) {}

  async publish(draft: ManuscriptDraft): Promise<ManuscriptRecord> {
    const title = draft.title.trim();
    if (title.length === 0) {
      throw new Error("Title must not be empty");
    }

    let coverToken = draft.coverToken;
    if (draft.coverBytes !== undefined) {
      await this.depot.put([...draft.coverBytes]);
    }

    const record: ManuscriptRecord = { title };
    if (coverToken !== undefined) {
      record.coverToken = coverToken;
    }
    const saved = await this.store.save(record);
    return { ...saved };
  }
}
```

