import { ManuscriptPublisher } from "./solution";
import type { BinaryDepot, ManuscriptDraft, ManuscriptRecord, ManuscriptStore } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

async function assertRejects(action: () => Promise<unknown>, expected: unknown): Promise<void> {
  try {
    await action();
  } catch (error: unknown) {
    assert(error === expected, "dependency error should propagate unchanged");
    return;
  }
  throw new Error("expected rejection");
}

async function main(): Promise<void> {
  const calls: string[] = [];
  let receivedBytes: readonly number[] | undefined;
  let receivedRecord: ManuscriptRecord | undefined;
  const depot: BinaryDepot = {
    async put(bytes: readonly number[]): Promise<string> {
      calls.push("put");
      receivedBytes = bytes;
      await Promise.resolve();
      return "uploaded-token";
    },
  };
  const store: ManuscriptStore = {
    async save(record: ManuscriptRecord): Promise<ManuscriptRecord> {
      calls.push("save");
      receivedRecord = record;
      return record;
    },
  };
  const publisher = new ManuscriptPublisher(depot, store);
  const originalBytes: readonly number[] = [1, 2, 3];
  const draft: ManuscriptDraft = { title: "  A manuscript  ", coverToken: "old-token", coverBytes: originalBytes };
  const before = JSON.stringify(draft);
  const published = await publisher.publish(draft);

  assert(calls.join(",") === "put,save", "cover upload must finish before saving");
  assert(receivedBytes !== originalBytes && JSON.stringify(receivedBytes) === "[1,2,3]", "cover bytes must be copied before upload");
  assert(receivedRecord !== undefined, "store should receive a record");
  assert(JSON.stringify(receivedRecord) === JSON.stringify({ title: "A manuscript", coverToken: "uploaded-token" }), "store should receive the trimmed title and uploaded token");
  assert(receivedRecord !== undefined && !("coverBytes" in receivedRecord), "saved record must not contain coverBytes");
  assert(JSON.stringify(draft) === before, "publish must not mutate its draft");
  assert(published !== receivedRecord, "publish must return a copy of the saved record");
  published.title = "changed";
  assert(receivedRecord !== undefined && receivedRecord.title === "A manuscript", "returned record must not alias the store result");

  let noCoverPutCount = 0;
  let noCoverSaved: ManuscriptRecord | undefined;
  const noCoverPublisher = new ManuscriptPublisher(
    { async put(): Promise<string> { noCoverPutCount += 1; return "unexpected"; } },
    { async save(record: ManuscriptRecord): Promise<ManuscriptRecord> { noCoverSaved = record; return { ...record }; } },
  );
  await noCoverPublisher.publish({ title: "Title", coverToken: "existing" });
  assert(noCoverPutCount === 0, "depot must not be called when coverBytes is absent");
  assert(noCoverSaved !== undefined && noCoverSaved.coverToken === "existing", "existing cover token should be saved when bytes are absent");

  let invalidCalls = 0;
  const invalidPublisher = new ManuscriptPublisher(
    { async put(): Promise<string> { invalidCalls += 1; return "x"; } },
    { async save(record: ManuscriptRecord): Promise<ManuscriptRecord> { invalidCalls += 1; return record; } },
  );
  try {
    await invalidPublisher.publish({ title: " \t " });
    throw new Error("expected title validation error");
  } catch (error: unknown) {
    assert(error instanceof Error && error.message === "Title must not be empty", "empty trimmed title should be rejected");
  }
  assert(invalidCalls === 0, "invalid titles must not call dependencies");

  const depotError = new Error("depot unavailable");
  let storeAfterDepotFailure = 0;
  const failingDepotPublisher = new ManuscriptPublisher(
    { async put(): Promise<string> { throw depotError; } },
    { async save(record: ManuscriptRecord): Promise<ManuscriptRecord> { storeAfterDepotFailure += 1; return record; } },
  );
  await assertRejects(() => failingDepotPublisher.publish({ title: "Valid", coverBytes: [9] }), depotError);
  assert(storeAfterDepotFailure === 0, "store must not run after upload failure");

  const storeError = new Error("store unavailable");
  const failingStorePublisher = new ManuscriptPublisher(
    { async put(): Promise<string> { return "token"; } },
    { async save(): Promise<ManuscriptRecord> { throw storeError; } },
  );
  await assertRejects(() => failingStorePublisher.publish({ title: "Valid" }), storeError);
}

void main();

